    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ValueError(f"malformed JSON: {e}")

    if not isinstance(data, dict):
        raise ValueError("root must be a JSON object")

    required_fields = {'update_id', 'version', 'platform', 'channel'}

    # Check all required fields are present
    for field in required_fields:
        if field not in data:
            raise ValueError(f"missing required field: {field}")

    # Validate update_id: must be a non-empty string
    if not isinstance(data['update_id'], str) or not data['update_id']:
        raise ValueError("update_id must be a non-empty string")

